package com.yazaki.printingservice.config;
import java.time.Instant; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
import com.yazaki.printingservice.api.dto.*; import com.yazaki.printingservice.application.*; import com.yazaki.printingservice.domain.model.*; import com.yazaki.printingservice.domain.repository.*;
@Component @Profile("dev") public class DevDemoDataInitializer implements ApplicationRunner {
 private final PrinterService printers; private final PrintJobService jobs; private final PrinterRepository printerRepository; private final PrintJobRepository jobRepository; @Value("${printing.demo-data.enabled:true}") boolean enabled;
 public DevDemoDataInitializer(PrinterService printers,PrintJobService jobs,PrinterRepository printerRepository,PrintJobRepository jobRepository){this.printers=printers;this.jobs=jobs;this.printerRepository=printerRepository;this.jobRepository=jobRepository;}
 @Override @Transactional public void run(ApplicationArguments args){if(!enabled||printerRepository.count()>0)return;var label=printers.create(new PrinterDtos.Upsert("DEMO-LABEL-01","Fictitious Label Printer",PrinterType.LABEL,"Demo Area A",null,PrinterStatus.ONLINE,null,true));var document=printers.create(new PrinterDtos.Upsert("DEMO-DOC-01","Fictitious Document Printer",PrinterType.DOCUMENT,"Demo Area B",null,PrinterStatus.OFFLINE,"demo-document-queue",true));
  var a=create("demo-001",label.id(),PrinterType.LABEL,"DEMO-ORDER-001");var b=create("demo-002",document.id(),PrinterType.DOCUMENT,"DEMO-ORDER-002");var c=create("demo-003",label.id(),PrinterType.LABEL,"DEMO-ORDER-003");jobRepository.findById(a.id()).orElseThrow().transitionTo(PrintJobStatus.SUBMITTED,Instant.now(),null,null);jobRepository.findById(b.id()).orElseThrow().transitionTo(PrintJobStatus.FAILED,Instant.now(),"DEMO_OFFLINE","Fictitious offline error");jobRepository.findById(c.id()).orElseThrow().scheduleRetry(Instant.now().plusSeconds(30),"DEMO_TIMEOUT","Fictitious timeout"); }
 private PrintJobDtos.Job create(String id,java.util.UUID printer,PrinterType type,String order){return jobs.create(new PrintJobDtos.Create("DEMO_SYSTEM",id,order,type,"{\"demo\":true}",printer,3)).job();}
}
